// per il braccio i, angolo di ancora: phi_i
function armContrib(theta, phi, params) {
  const u = signedAngleDiff(theta, phi); // in [-PI, PI]
  if (Math.abs(u) > params.halfWidth) return 0;

  const t = Math.abs(u) / params.halfWidth; // 0=centro, 1=bordo

  // collo: restringimento a t ~ 0.25, poi espansione, poi taper
  const neck   = 1 - params.neckDepth * bell(t, 0.25, 0.10);
  const expand = 1 + params.midBulge * bell(t, 0.55, 0.18);
  const tip    = Math.pow(1 - t, params.tipExp); // rastremazione finale

  return params.length * neck * expand * tip;

